   284→                        totalLength += length;
   285→                        rlpStream.SkipBytes(length);
   286→                    }
   287→                    else
   288→                    {
   289→                        if (ReferenceEquals(data, _nullNode) || data is null)
   290→                        {
   291→                            totalLength++;
   292→                        }
   293→                        else if (data is Hash256)
   294→                        {
