   340→                    }
   341→                    else
   342→                    {
   343→                        path.AppendMut(i);
   344→                        Debug.Assert(data is TrieNode, "Data is not TrieNode");
   345→                        TrieNode childNode = Unsafe.As<TrieNode>(data);
   346→                        childNode!.ResolveKey(tree, ref path, bufferPool: bufferPool);
   347→                        path.TruncateOne();
   348→
   349→                        hash = childNode.Keccak;
   350→                        if (hash is null)
   351→                        {
   352→                            Span<byte> fullRlp = childNode.FullRlp.Span;
   353→                            fullRlp.CopyTo(destination.Slice(position, fullRlp.Length));
   354→                            position += fullRlp.Length;
   355→                        }
   356→                        else
   357→                        {
   358→                            position = Rlp.Encode(destination, position, hash);
   359→                        }
   360→                    }
   361→                }
