   393→                            Debug.Assert(data is TrieNode, "Data is not TrieNode");
   394→                            TrieNode childNode = Unsafe.As<TrieNode>(data);
   395→                            childNode!.ResolveKey(tree, ref path, bufferPool: bufferPool);
   396→                            path.TruncateOne();
